import {KEY,SOURCES,CATALOG,TERMS,initial,example,totals,coverage,validateState,normalizeCourse} from './model.js';
let state=initial(),tab='overview';try{const saved=JSON.parse(localStorage.getItem(KEY));if(validateState(saved))state=saved;}catch{}
const $=s=>document.querySelector(s),all=s=>document.querySelectorAll(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let timer;function toast(s){clearTimeout(timer);$('#toast').textContent=s;$('#toast').classList.add('show');timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Storage unavailable. Export your plan to keep it.')}render()}
const tag=(s,color='')=>`<span class="tag ${color}">${s}</span>`;
const options=(list,value)=>list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
function heading(label,title,desc){return `<div class="eyebrow">${label}</div><h1>${title}</h1><p class="subtitle">${desc}</p>${state.example?'<div class="notice">Fictional example loaded. These courses and dates do not describe a real student.</div>':''}`}
function row(title,value,max,note){return `<div class="progress-row"><div class="row-top"><span>${title}</span><span class="small">${value} / ${max} credits</span></div><div class="track"><div style="width:${Math.min(100,value/max*100)}%"></div></div><p>${note}</p></div>`}
function profileForm(){return `<section class="card"><div class="card-heading"><h2>Set your planning horizon</h2>${tag('Coursework option only','gray')}</div><form id="profile" class="form-row"><label>Graduation target<select id="graduation">${options(['Not set',...TERMS],state.graduation)}</select></label>${state.terms.map((term,i)=>`<label>Semester ${i+1}<select id="term-${i}">${options(TERMS,term)}</select></label>`).join('')}<button class="button">Save horizon</button></form><p class="small">Supports the MSCS Machine Learning coursework option using a June 2026 rule snapshot. Confirm your applicable catalog and approvals.</p></section>`}
function overview(){const t=totals(state);return heading('YOUR NEXT CHAPTER','A clearer path to your MS.','Bring your course history and goals together. See the gaps, explore semesters, and investigate a possible term abroad.')+`
 ${!state.courses.length?'<section class="card"><h2>Start with your courses.</h2><p class="small">Add completed or in-progress courses, then select which count toward your MS. Your records stay in this browser.</p><div class="form-row"><button class="button" data-go="credits">Add your first course +</button><button class="button secondary" id="example">Explore a fictional example</button></div></section>':''}
 <div class="stats"><div class="stat"><div class="label">MS degree target</div><strong>30 <span>credits</span></strong><span>Coursework option</span></div><div class="stat"><div class="label">Allocated toward MS</div><strong>${t.credits} <span>credits</span></strong><span>${t.earned} earned · ${t.credits-t.earned} in progress</span></div><div class="stat focus"><div class="label">Still to plan</div><strong>${t.remaining} <span>credits</span></strong><span>Provisional credit allocation</span></div><div class="stat"><div class="label">Graduation target</div><strong style="font-size:23px;padding:5px 0">${esc(state.graduation)}</strong><span>Set your horizon below</span></div></div>
 <div class="grid"><section class="card"><div class="card-heading"><h2>Your requirement map</h2>${tag('ML specialization')}</div>${row('Core · Algorithms',t.alg,3,'One approved algorithms core course.')}${row('Core · Machine Learning',t.ml,3,'One approved machine learning core course.')}${row('Machine Learning electives',t.elect,9,'Three approved specialist electives, typically 3 credits each.')}${row('Free electives',t.free,15,'Remaining eligible coursework; each credit is allocated only once.')}<div class="notice">${state.includeIP?'Includes in-progress courses.':'Earned credits only.'} MS acceptance and completion still need confirmation.</div><button class="inline-link" data-go="credits">Review course designations →</button></section><div><section class="card"><h2>One semester at a time</h2><div class="timeline" style="grid-template-columns:1fr">${state.terms.map(term=>`<div class="milestone"><span class="small">${esc(term.toUpperCase())}</span><strong>${state.plan.filter(c=>c.term===term).reduce((n,c)=>n+c.credits,0)} credits planned</strong><p>${state.plan.filter(c=>c.term===term).map(c=>esc(c.code)).join(' · ')||'An open semester to explore'}</p></div>`).join('')}</div><button class="inline-link" style="margin-top:18px" data-go="courses">Build a scenario →</button></section><section class="card"><h3>Keep the evidence visible</h3><p class="small">${t.pending} course designation${t.pending===1?'':'s'} awaiting confirmation. Current selections use ${t.limited}/6 credits of the 4000-level / non-CS/CSE allowance.</p><button class="inline-link" data-go="sources">Read the source rules →</button></section></div></div>${profileForm()}`}
function courseEntry(id,label,planned=false){const available=CATALOG.filter(c=>!state.courses.some(x=>x.code===c.code&&x.designation!=='bs')&&!state.plan.some(x=>x.code===c.code));return `<section class="card"><h2>${label}</h2><form id="${id}" style="margin-top:18px"><div class="form-row"><label>Course from worksheet<select name="catalog"><option value="custom">Enter another course</option>${available.map(c=>`<option value="${c.code}">${esc(c.code)} · ${esc(c.title)}</option>`).join('')}</select></label><label>Course code<input name="code" type="text" placeholder="e.g. CS 7641" maxlength="12"></label><label>Title<input name="title" type="text" placeholder="For a course not listed" maxlength="120"></label></div><div class="form-row" style="margin-top:12px"><label>Credits<select name="credits">${options(['1','2','3','4','5','6'],'3')}</select></label>${planned?`<label>Semester<select name="term">${options(state.terms,state.terms[0])}</select></label>`:`<label>Grade / status<select name="grade">${options(['IP','A','B','C','D','F'],'IP')}</select></label><label>Designation<select name="designation"><option value="ms">MS only</option><option value="double">Double-count BS/MS</option><option value="bs">BS only</option></select></label>`}<button class="button">${planned?'Add to plan +':'Add course +'}</button></div></form><p class="small">Known courses receive worksheet categories. Other 4000–8000-level courses are provisional free electives, pending eligibility review. “IP” means in progress.</p></section>`}
function credits(){return heading('01 / CREDIT MAP','Start with what you’ve done.','Enter completed or in-progress courses and their intended MS designation. This app does not import an audit PDF yet.')+courseEntry('add-record','Add a course record')+`<section class="card"><div class="card-heading"><h2>Your course records</h2>${tag(`${state.courses.length} courses`,'gray')}</div>${state.courses.length?`<div class="table-wrap"><table><thead><tr><th>COURSE</th><th>CREDITS</th><th>GRADE / STATUS</th><th>DESIGNATION</th><th>MS APPROVAL</th><th></th></tr></thead><tbody>${state.courses.map((c,i)=>`<tr><td><strong>${esc(c.code)}</strong><small>${esc(c.title)}</small></td><td>${c.credits}</td><td><select aria-label="Grade for ${esc(c.code)}" data-grade="${i}">${options(['A','B','C','D','F','IP'],c.grade)}</select></td><td><select aria-label="Designation for ${esc(c.code)}" data-designation="${i}">${[['double','Double-count BS/MS'],['ms','MS only'],['bs','BS only']].map(([v,l])=>`<option value="${v}" ${c.designation===v?'selected':''}>${l}</option>`).join('')}</select></td><td><label><input type="checkbox" data-approved="${i}" ${c.approved?'checked':''}> Confirmed</label></td><td><button class="inline-link" data-delete="${i}" aria-label="Delete ${esc(c.code)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No courses entered yet.</p>'}<div class="settings" style="margin-top:20px"><label><input id="include-ip" type="checkbox" ${state.includeIP?'checked':''}> Include in-progress credits in the baseline</label></div><p class="small">“Confirmed” records that you verified eligibility with an advisor. Fallthrough and BS cross-listing do not themselves prove MS approval. GPA, course equivalencies and the BS side of double-counting are not validated.</p></section><button class="reset" id="reset">Clear local workspace</button>`}
function courses(){const t=totals(state),p=coverage(state);return heading('02 / SEMESTER PLANNER','Make the semesters work for you.','Build a scenario using candidate courses. Published offerings, prerequisites and registration access must be checked separately.')+`<div class="requirements"><div class="card"><span class="small">ALGORITHMS CORE LEFT</span><strong class="big">${Math.max(0,3-t.alg)} credits</strong></div><div class="card"><span class="small">ML CORE + ELECTIVES LEFT</span><strong class="big">${Math.max(0,3-t.ml)+Math.max(0,9-t.elect)} credits</strong></div><div class="card"><span class="small">FREE ELECTIVES LEFT</span><strong class="big">${Math.max(0,15-t.free)} credits</strong></div></div>${courseEntry('add-plan','Add a course candidate',true)}<div class="semesters">${state.terms.map(term=>{const cs=state.plan.filter(c=>c.term===term);const abroad=state.abroad&&term===state.abroadTerm;return `<section class="semester ${abroad?'abroad':''}"><div class="statusline"><h3>${esc(term)}</h3>${tag(`${cs.reduce((n,c)=>n+c.credits,0)} cr`,'gray')}</div><span class="small">${abroad?'Abroad scenario · approval unresolved':'Term offering unverified'}</span>${cs.length?cs.map(c=>`<div class="course-chip"><strong>${esc(c.code)} · ${c.credits} cr</strong><button class="remove" aria-label="Remove planned ${esc(c.code)}" data-remove="${esc(c.code)}">×</button><p>${esc(c.title)}</p>${tag(c.kind==='alg'?'Algorithms':c.kind==='ml'?'ML core':c.kind==='elective'?'ML / free elective':'Provisional free elective')}</div>`).join(''):'<div class="empty">No courses placed yet.</div>'}</section>`}).join('')}</div><section class="card" style="margin-top:20px"><h2>Projected requirement coverage</h2>${row('Total credits',p.credits,30,'Assumes all entered in-progress and planned courses are completed and accepted.')}${row('Algorithms core',p.alg,3,'One approved algorithms course required.')}${row('Machine Learning core',p.ml,3,'One approved ML core course required.')}${row('ML electives',p.elect,9,'Approved specialist coursework.')}${row('Free electives',p.free,15,'Extra specialist credits flow here without counting them twice.')}${row('Graduate CS/CSE credits',p.graduate,24,'At least 24 credits at level 6000–8000.')}<div class="notice">${p.limited>6?'Over the 6-credit 4000-level / non-CS/CSE allowance.':`${p.limited}/6 credits of the 4000-level / non-CS/CSE allowance used.`} ${p.credits>30?'More than 30 credits are planned.':''}</div><p class="small">A filled credit map is not graduation approval. This prototype does not validate GPA, prerequisites, equivalent or repeated courses, meeting times, offerings, residency, or institutional approvals.</p></section>${profileForm()}`}
const checklist=[['Program eligibility','Can a graduate MSCS student join the specific program?'],['Course equivalencies','Which host courses have approved MS equivalents?'],['Graduation logistics','Will credit posting, residency and graduation deadlines fit?'],['Term offerings','Will enough suitable courses be offered during your visit?']];
function abroad(){const cs=state.plan.filter(c=>c.term===state.abroadTerm);return heading('03 / STUDY ABROAD','Leave room to go somewhere.','Investigate a semester abroad alongside your plan. No exchange program or course equivalency has been verified by this app.')+`<div class="two-column"><section class="card"><h2>Your abroad scenario</h2><div class="settings" style="margin:20px 0"><label><input id="abroad" type="checkbox" ${state.abroad?'checked':''}> Explore studying abroad</label></div><label class="small">Target semester <select id="abroad-term">${options(TERMS,state.abroadTerm)}</select></label><div class="milestone" style="margin-top:20px"><strong>${esc(state.abroadTerm)}</strong><p>${cs.reduce((n,c)=>n+c.credits,0)} credits placed · Graduation target: ${esc(state.graduation)}</p></div>${cs.map(c=>`<div class="source"><strong>${esc(c.code)} · ${esc(c.title)}</strong><p>Host offering and equivalency still need confirmation.</p>${tag('Unverified','amber')}</div>`).join('')}<p class="notice">${state.terms.includes(state.abroadTerm)?'Select a program and confirm the graduate rules before treating this scenario as feasible.':'This term is outside your current planning horizon. Update the horizon to place courses in it.'}</p><a href="https://ea.oie.gatech.edu/exchange-credit-transfer-instructions" target="_blank" rel="noopener">Read OIE’s guidance ↗</a></section><section class="card"><div class="card-heading"><h2>Questions to resolve</h2>${tag(`${state.checks.filter(Boolean).length}/4 reviewed`,'gray')}</div><ul class="checklist">${checklist.map(([title,note],i)=>`<li><input type="checkbox" data-check="${i}" aria-label="Reviewed: ${title}" ${state.checks[i]?'checked':''}><span>${title}<small>${note}</small></span></li>`).join('')}</ul><p class="small">A checkmark records your review, not an institutional approval. Export the plan for an advising conversation.</p></section></div>`}
function sourceResults(q){const words=q.toLowerCase().trim().split(/\s+/).filter(Boolean);const list=SOURCES.filter(s=>words.every(w=>(s.title+' '+s.text).toLowerCase().includes(w)));return list.length?list.map(s=>`<article class="source"><a href="${s.url}" target="_blank" rel="noopener">${s.title} ↗</a><p>${s.text}</p><span class="small">${s.date}</span></article>`).join(''):'<p class="empty">No match. Try “credits”, “electives”, or “transfer”.</p>'}
function sources(){return heading('04 / SOURCES & RULES','Know what the plan is based on.','Review source links and limitations. Requirements use a fixed snapshot, not a live policy feed.')+`<section class="card"><h2>Source library</h2><input class="search" type="search" id="search" aria-label="Search sources" placeholder="Search sources: credits, electives, transfer…"><div id="results">${sourceResults('')}</div></section><section class="card"><h2>Scope of this release</h2><p class="small">MSCS Machine Learning coursework planning, manual course entry, rule-based credit matching, semester scenarios, and browser-local import/export. The worksheet list is a selected subset; custom courses are provisional free electives.</p><h3 style="margin-top:20px">Planned retrieval features</h3><p class="small">Audit PDF ingestion, syllabus indexing, vector search, cited AI explanations, live offerings, and retrieval evaluations are not implemented. Search above is keyword filtering, not RAG.</p><a href="https://github.com/sgandotra1/gt-path" target="_blank" rel="noopener">View the implementation and roadmap ↗</a></section>`}
function render(){all('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});$('#content').innerHTML=({overview,credits,courses,abroad,sources})[tab]();bind()}
function go(next){tab=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function addRecord(form,planned){const data=new FormData(form);let c;try{const code=data.get('catalog');c=code==='custom'?normalizeCourse(data.get('code'),data.get('title')):{...CATALOG.find(c=>c.code===code)};c.credits=Number(data.get('credits'));if(!c.title)throw Error('Enter a title for an unlisted course.');if(state.courses.some(x=>x.code===c.code&&(!planned||x.designation!=='bs'))||state.plan.some(x=>x.code===c.code))throw Error('That course is already recorded or planned.');if(planned)state.plan.push({...c,term:data.get('term')});else state.courses.push({...c,grade:data.get('grade'),designation:data.get('designation'),approved:false});state.example=false;save();toast(`${c.code} added`)}catch(e){toast(e.message)}}
function bind(){all('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));all('[data-grade]').forEach(el=>el.onchange=()=>{state.courses[+el.dataset.grade].grade=el.value;save()});all('[data-designation]').forEach(el=>el.onchange=()=>{const c=state.courses[+el.dataset.designation];c.designation=el.value;if(c.designation!=='bs')state.plan=state.plan.filter(x=>x.code!==c.code);save()});all('[data-approved]').forEach(el=>el.onchange=()=>{state.courses[+el.dataset.approved].approved=el.checked;save()});all('[data-delete]').forEach(b=>b.onclick=()=>{state.courses.splice(+b.dataset.delete,1);save()});all('[data-remove]').forEach(b=>b.onclick=()=>{state.plan=state.plan.filter(c=>c.code!==b.dataset.remove);save()});all('[data-check]').forEach(el=>el.onchange=()=>{state.checks[+el.dataset.check]=el.checked;save()});if($('#include-ip'))$('#include-ip').onchange=e=>{state.includeIP=e.target.checked;save()};if($('#abroad'))$('#abroad').onchange=e=>{state.abroad=e.target.checked;save()};if($('#abroad-term'))$('#abroad-term').onchange=e=>{state.abroadTerm=e.target.value;save()};if($('#search'))$('#search').oninput=e=>$('#results').innerHTML=sourceResults(e.target.value);if($('#add-record'))$('#add-record').onsubmit=e=>{e.preventDefault();addRecord(e.target,false)};if($('#add-plan'))$('#add-plan').onsubmit=e=>{e.preventDefault();addRecord(e.target,true)};if($('#example'))$('#example').onclick=()=>{state=example();save();toast('Fictional example loaded')};if($('#reset'))$('#reset').onclick=()=>{if(confirm('Clear your locally saved course records and plan?')){state=initial();save();toast('Local workspace cleared')}};if($('#profile'))$('#profile').onsubmit=e=>{e.preventDefault();const terms=[0,1,2].map(i=>$(`#term-${i}`).value);if(new Set(terms).size<3)return toast('Choose three different semesters.');if(state.plan.some(c=>!terms.includes(c.term)))return toast('Remove or finish planning courses in terms you want to replace.');state.graduation=$('#graduation').value;state.terms=terms;save();toast('Planning horizon saved')}}
all('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();go('overview')};all('.export').forEach(b=>b.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='gt-path-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Plan exported')});all('.import-file').forEach(el=>el.onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error();const s=JSON.parse(await file.text());if(!validateState(s))throw Error();state=s;save();toast('Plan imported')}catch{toast('Choose a valid version 2 GT Path JSON export.')}finally{e.target.value=''}});render();
